// Map Monday.com column_values into flatten object.

const COLUMNS = [
  'Name',
  'Date',
  'Status',
  'Owner',
  'Email',
  'Phone',
  'Location',
  'Files',
];

const output = $input.all().map(item => {
  const json = item.json || {};
  const row = {};

  row['Name'] = json.name ?? '';

  if (Array.isArray(json.column_values)) {
    for (const col of json.column_values) {
      const title = col.column?.title;
      if (COLUMNS.includes(title)) {
        row[title] = col.text ?? '';
      }
    }
  }

  return {
    json: Object.fromEntries(COLUMNS.map(col => [col, row[col] ?? '']))
  };
});

return output;
